-- Tabelle erstellen CREATE TABLE passwoerter ( id INTEGER PRIMARY KEY, passwort TEXT NOT NULL, beschreibung TEXT NOT NULL );
-- Beispieldaten einfügen INSERT INTO passwoerter (id, passwort, beschreibung) VALUES (1, 'qwert1234', 'Standardpasswort für alte Router'), (2, 'supersecure99', 'Super-sicheres Passwort für das Schulnetzwerk'), (3, 'bananaSplit', 'Passwort für die Kantine'), (4, 'password123', 'Standardpasswort'), (5, 'h@ckM3', 'Passwort für den geheimen Testserver'), (6, 'kanuFun', 'Passwort für die Ruder-Meisterschaft'), (7, 'letmein2024', 'Passwort für den Büroeingang'), (8, 'catLover88', 'Passwort für das Katzenforum'), (10, 'DiscoDance!', 'Steuerung der Partybeleuchtung'), (11, 'pa$$w0rd', 'Wegwerf-E-Mail-Adresse'), (12, '9823', 'Für den Drucker neben dem Sekretariat'), (13, 'secureP@ss!', 'Für die verschlossene Schublade im Büro'), (15, '4234', 'PIN für die Schulalarmanlage');
CREATE TABLE inventar ( id INTEGER PRIMARY KEY, gegenstand TEXT NOT NULL, anzahl INTEGER NOT NULL, beschreibung TEXT NOT NULL );
INSERT INTO inventar (id, gegenstand, anzahl, beschreibung) VALUES (1023, 'HDMI-Kabel', 5, 'Funktionierende HDMI-Kabel, geeignet für Apple-TV-Geräte'), (2048, 'VGA-Kabel', 3, 'Veraltete Kabel, kaum noch im Einsatz'), (3567, 'Netzwerkkabel', 10, 'Lange Netzwerkkabel, Cat-6, perfekt für Präsentationen'), (4562, 'Logitech-Maus, kabelgebunden', 3, 'Klassische Maus der Marke Logitech'), (4567, 'Logitech-Maus, drahtlos', 5, 'Maus der Marke Logitech mit Funkverbindung'), (4789, 'Beamer', 2, 'HD-Beamer, geeignet für große Räume'), (5123, 'Lautsprecher', 4, 'Kompakte Lautsprecher für Präsentationen'), (4682, 'Asus-Maus', 6, 'Maus der Marke Asus mit Funkverbindung'), (6781, 'Laserpointer', 6, 'Praktische Laserpointer für Vorträge und Präsentationen'), (7219, 'HDMI-Adapter', 2, 'Adapter für Geräte mit HDMI-Ausgang'), (8903, 'Whiteboard-Marker', 20, 'Verschiedene Farben, geeignet für Whiteboards');
CREATE TABLE inbox ( id INTEGER PRIMARY KEY, absender TEXT NOT NULL, betreff TEXT NOT NULL, inhalt TEXT NOT NULL, empfangen_am DATETIME NOT NULL );
INSERT INTO inbox (id, absender, betreff, inhalt, empfangen_am) VALUES (1001, 'info@bildung.de', 'Fortbildung Reminder', 'Erinnerung: Fortbildung am 25.11.2024 in Hamburg.', '2024-09-11 15:23:00'), (1002, 'anna.mueller@student.schule.de', 'Passwort für IServ', 'Ich benötige ein neues Passwort für IServ. Vielen Dank!', '2024-09-12 02:45:00'), (1003, 'kollege@schule.de', 'Vertretungsplan', 'Bitte aktualisieren Sie den Vertretungsplan für nächste Woche.', '2024-09-11 08:00:00'), (1004, 'verwaltung@schule.de', 'Raumbelegung', 'Hier ist die Raumbelegung für den kommenden Monat.', '2024-09-12 01:15:00'), (1005, 'info@stadtbibliothek.de', 'Ausleihe verlängert', 'Ihre Ausleihe wurde bis zum 05.12.2024 verlängert.', '2024-09-11 12:45:00'), (1006, 'freund@schule.ch', 'Grüße aus der Schweiz', 'Wir möchten euch herzlich grüßen und hoffen, euch bald zu sehen.', '2024-09-12 05:00:00'), (1007, 'max.mustermann@student.schule.de', 'Passwort zurücksetzen', 'Sehr geehrter Herr Schulleiter, ich habe mein Passwort für das Notenportal vergessen. Bitte setzen Sie es zurück.', '2024-09-11 10:30:00'), (1008, 'partner@highschool.silicon-valley.edu', 'Delegation aus Amerika', 'My dear colleague! Wir grüßen Sie ganz herzlich! Uns wurde soeben bewilligt, mit 30 Schülern und 3 Lehrkräften zu Ihnen zu reisen, um das geplante IT-Projekt mit Schülern Ihrer Schule umzusetzen. Wir werden in 2 Wochen am Flughafen Hamburg ankommen. Wäre es möglich, Unterkünfte für uns bereitzustellen? Wir freuen uns bereits! Best wishes! Yours, Alastair McGolla', '2024-09-12 03:30:00'), (1009, 'elternvertreter@eltern.de', 'Anfrage zur Elternversammlung', 'Wann findet die nächste Elternversammlung statt? Wir benötigen Informationen.', '2024-09-11 14:15:00'), (1010, 'sekretariat@schule.de', 'IT-Wartung geplant', 'Hinweis: Am 23.11.2024 ist die IT-Wartung für Cevex geplant.', '2024-09-11 11:00:00'), (1011, 'lisa.schueler@student.schule.de', 'Dringend: Passwort für Notenportal', 'Ich kann mich nicht mehr anmelden im Notenportal. Bitte setzen Sie mein Passwort zurück!', '2024-09-12 03:15:00'), (1019, 'clara.klug@student.schule.de', 'Notenportal', 'Bitte helfen Sie mir, mein Notenportal ist defekt!', '2024-09-12 03:15:00'), (1020, 'tom.neumann@student.schule.de', 'Notenportal: Zugang vergessen', 'Ich habe mein Passwort vergessen. Bitte helfen Sie mir beim Anmelden!', '2024-09-12 02:30:00'), (1012, 'benjamin.bauer@student.schule.de', 'Passwort vergessen', 'Guten Tag, ich habe das Passwort für IServ vergessen. Bitte helfen Sie mir!', '2024-09-11 16:45:00'), (1013, 'hausmeister@schule.de', 'Defekte Tür in Raum 103', 'Die Tür in Raum 103 klemmt. Ich werde mich darum kümmern.', '2024-09-12 07:30:00'), (1014, 'maria.lehrer@schule.de', 'Fachkonferenz verschieben', 'Können wir die Fachkonferenz auf nächste Woche verschieben?', '2024-09-11 09:00:00');
-- Tabelle für Gäste erstellen CREATE TABLE gaeste ( name VARCHAR(50) PRIMARY KEY, fach_a VARCHAR(50), fach_b VARCHAR(50) );
-- Einträge in die Tabelle "gaeste" einfügen INSERT INTO gaeste (name, fach_a, fach_b) VALUES ('Mr. A. McGolla', 'Mathematik', 'Physik'), ('Mrs. H. Wrincker', 'Informatik', 'Mathematik'), ('Mr. C. Broomhard', 'Biologie', 'Deutsch');
-- Tabelle für Kollegium erstellen CREATE TABLE kollegium ( name VARCHAR(50) PRIMARY KEY, fach_a VARCHAR(50), fach_b VARCHAR(50) );
