-- Abfrage zur Zuordnung der Gäste mit einem Join basierend auf den Fächerkombinationen SELECT g.name AS Gast, k.name AS Unterkunft_beim_Kollegen FROM gaeste g JOIN kollegium k ON (g.fach_a = k.fach_a AND g.fach_b = k.fach_b) OR (g.fach_a = k.fach_b AND g.fach_b = k.fach_a);
